 IEnumerator Start(){folder=SportsEvidencePaths.Folder("MattressEvidence");yield return SportsProbeScene.Ensure<MattressMatch>("TruckMattressRacing");m=FindAnyObjectByType<MattressMatch>();yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;m.AllBots();m.option=1;Check(m.StartMatch(),"eight-AI mattress setup starts");Time.timeScale=4;while(m.Phase==MattressPhase.Countdown)yield return null;Check(m.racers.All(r=>!r.truck.Powered&&r.truck.wheels.All(w=>!w.enabled)),"zero powered or hidden driving tires on all eight platforms");var first=m.racers[0];first.truck.body.position=m.course.Surface(new Vector3(70,0,0))+Vector3.up;yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();Check(first.Phase==MattressAttempt.Recovery&&first.Recoveries==1&&first.Checkpoint==0&&first.truck.body.position.z<=8.01f,"genuine off-course recovery returns to last passed checkpoint without progress skip");float recovery=first.RecoveryRemaining;m.Pause();var p=first.truck.body.position;float clock=m.RaceTime;yield return new WaitForSecondsRealtime(.2f);Check(first.RecoveryRemaining==recovery&&p==first.truck.body.position&&clock==m.RaceTime,"pause preserves recovery penalty bodies and clock");m.Resume();Time.timeScale=4;yield return new WaitForSeconds(5.2f);Check(first.Phase==MattressAttempt.Racing&&m.RaceTime-clock>=5,"fixed five-second recovery penalty expires while race continues");
