ime.realtimeSinceStartup+2;}yield return null;}
 tally.Verify(slot=>m.series.total[slot],Check);Check(awardCaptured,"actual first placement award captured");if(m.Finished)yield return SportsResultsAcceptance.Capture(m,Check,folder,m.ResultPlace,slot=>(double?)m.series.total[slot],slot=>m.series.winner==slot);
 Check(m.Finished&&m.series.winner>=0&&m.series.completed>=3,"complete physical three-race series and winner");Check(moved&&arrivals>=8,"gravity motion and actual ordered-checkpoint finishes occur");Check(finishedOnce.All(value=>value),"every competitor can physically finish during the three-race series");Check(m.racers.All(r=>!r.truck.Powered&&r.truck.wheels.All(w=>!w.enabled)),"all-race physics never enabled hidden tires");log.AppendLine("MATCH races="+m.series.completed+" winner="+m.series.winner+" total="+string.Join(",",m.series.total)+" ERRORS="+errors+". Actual PhysX/NWH-disabled gravity platforms and AI weight controls; no hardware/human playtest.");m.SetupScreen();Check(m.StartMatch()&&m.series.completed==0&&m.ScoreJournal.Count==0&&m.series.total.All(p=>p==0),"rematch clears original series and presentation journal");m.SetupScreen();log.AppendLine("CHECKS="+checks+" ERRORS="+errors);File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("MATTRESS_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){tally?.Dispose();Restore();preferences?.Dispose();SportsParticipantRegistry.ForgetCache();}
